typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;for(;;){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(n>0)h[i]=last;return top;}

/* returns 0 ok, 1 infeasible */
static int sap(int n,const double*M,const int*cnt,const int*adj,double*u,double*v,int*c4r,int*r4c,
  double*sh,int*path,char*SC,int*scl,int*srl,HE*heap){
  for(int i=0;i<n;i++){u[i]=0;c4r[i]=-1;} for(int j=0;j<n;j++){v[j]=0;r4c[j]=-1;sh[j]=INFINITY;SC[j]=0;}
  for(int cur=0;cur<n;cur++){
    int nsc=0,nsr=0,hs=0,sink=-1;double minv=0;
    int i=cur; double di=0; srl[nsr++]=cur;
    for(;;){
      const int*a=adj+(size_t)i*n; const double*Mi=M+(size_t)i*n; double ui=u[i];
      for(int t=0;t<cnt[i];t++){int k=a[t]; if(SC[k])continue; double r=di+Mi[k]-ui-v[k];
        if(r<sh[k]){sh[k]=r;path[k]=i;hpush(heap,&hs,r,k);} }
      int j=-1;
      while(hs>0){HE e=hpop(heap,&hs); if(SC[e.j]||e.d>sh[e.j])continue; j=e.j;break;}
      if(j<0){ for(int t=0;t<n;t++){sh[t]=INFINITY;SC[t]=0;} return 1;}
      SC[j]=1;scl[nsc++]=j;minv=sh[j];
      if(r4c[j]<0){sink=j;break;}
      i=r4c[j];di=minv;srl[nsr++]=i;
    }
    u[cur]+=minv;
    for(int t=1;t<nsr;t++){int r=srl[t];u[r]+=minv-sh[c4r[r]];}
    for(int t=0;t<nsc;t++){int c=scl[t];v[c]-=minv-sh[c];}
    /* reset sh for all touched: touched cols are in heap history; reset all cheaply */
    int j=sink;
