  for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; int m=0;
    for(int j=0;j<n;j++){double d=Mi[j]-v[j]; if(m<k||d<bd[m-1]){int p=(m<k)?m++:m-1; while(p>0&&bd[p-1]>d){bd[p]=bd[p-1];bj[p]=bj[p-1];p--;} bd[p]=d;bj[p]=j;}}
    cnt[i]=m; for(int t=0;t<m;t++){adj[(size_t)i*n+t]=bj[t];has[(size_t)i*n+bj[t]]=1;}
