        const double*Mi=M+(size_t)i*n; int m=0;
        for(int j=0;j<n;j++){ if(has[(size_t)i*n+j])continue; double d=Mi[j]-v[j]; if(m<k||d<bd[m-1]){int p=(m<k)?m++:m-1; while(p>0&&bd[p-1]>d){bd[p]=bd[p-1];bj[p]=bj[p-1];p--;} bd[p]=d;bj[p]=j;}}
        for(int t=0;t<m;t++){adj[(size_t)i*n+cnt[i]++]=bj[t];has[(size_t)i*n+bj[t]]=1;add++;}
      }
      if(!add) break; continue;
    }
    int viol=0;
    for(int i=0;i<n;i++){const double*Mi=M+(size_t)i*n; double ui=u[i];
      for(int j=0;j<n;j++){ if(Mi[j]-ui-v[j]< -1e-12 && !has[(size_t)i*n+j]){adj[(size_t)i*n+cnt[i]++]=j;has[(size_t)i*n+j]=1;viol++;}}}
    if(!viol){ret=it;break;}
  }
  free(cnt);free(adj);free(has);free(u);free(v);free(sh);free(r4c);free(path);free(scl);free(srl);free(touched);free(SC);free(heap);free(bd);free(bj);
  return ret;
