}
static int hs_;
static inline void hpush2(double d,int j){ if(hs_>=heapcap){heapcap*=2;heap=realloc(heap,sizeof(HE)*heapcap);} hpush(heap,&hs_,d,j);}

static int sap(int n,const double*M,int*c4r){
  for(int cur=0;cur<n;cur++){
    if(c4r[cur]>=0)continue;
