      if(j<0){ for(int t=0;t<nt;t++){sh[touched[t]]=INFINITY;SC[touched[t]]=0;} return 1;}
      SC[j]=1;scl[nsc++]=j;minv=sh[j];
      if(r4c[j]<0){sink=j;break;}
      i=r4c[j];di=minv;srl[nsr++]=i;
    }
    u[cur]+=minv;
    for(int t=1;t<nsr;t++){int r=srl[t];u[r]+=minv-sh[c4r[r]];}
    for(int t=0;t<nsc;t++){int c=scl[t];v[c]-=minv-sh[c];}
    int j=sink;
    for(;;){int r=path[j];r4c[j]=r;int tmp=c4r[r];c4r[r]=j;if(r==cur)break;j=tmp;}
