/* set u = row min reduced over adj; keep tight matches; greedy fill */
static void reinit(int n,const double*M,int*c4r){
  for(int i=0;i<n;i++){const int*a=adj+(size_t)i*n;const double*Mi=M+(size_t)i*n;double mn=INFINITY;int am=-1;
    for(int t=0;t<cnt[i];t++){int k=a[t];double r=Mi[k]-v[k];if(r<mn){mn=r;am=k;}}
    u[i]=mn;
    int c=c4r[i];
    if(c>=0){ if(Mi[c]-v[c]-mn>1e-13){r4c[c]=-1;c4r[i]=-1;} }
    if(c4r[i]<0 && am>=0 && r4c[am]<0){c4r[i]=am;r4c[am]=i;}
  }
}

static void topk(int n,const double*M,int k,int add){
  double bd[256]; int bj[256];
  for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; const char*hi=has+(size_t)i*n; int m=0; double thr=INFINITY;
    for(int j=0;j<n;j++){double d=Mi[j]-v[j]; if(d<thr){ if(add&&hi[j])continue; int p=(m<k)?m++:m-1; while(p>0&&bd[p-1]>d){bd[p]=bd[p-1];bj[p]=bj[p-1];p--;} bd[p]=d;bj[p]=j; if(m==k)thr=bd[k-1];}}
