    if(!add)cnt[i]=0;
    for(int t=0;t<m;t++){ai[cnt[i]++]=bj[t];hw[bj[t]]=1;}
  }
}

double TT[8];
int solve(int n,const double*M,int k,int*c4r){
  double T0=now();
  ensure(n); memset(has,0,(size_t)n*n);
  if(k>n)k=n; if(k>255)k=255;
  for(int j=0;j<n;j++){v[j]=INFINITY;r4c[j]=-1;sh[j]=INFINITY;}
  for(int i=0;i<n;i++){c4r[i]=-1;const double*Mi=M+(size_t)i*n;for(int j=0;j<n;j++)v[j]=Mi[j]<v[j]?Mi[j]:v[j];}
  double T1=now();
  topk(n,M,k,0);
  double T2=now(); TT[3]=TT[4]=0;
  int ret=-1;
  for(int it=0;it<200;it++){
    double a0=now();
    reinit(n,M,c4r);
    int st=sap(n,M,c4r);
    double a1=now(); TT[3]+=a1-a0;
    if(st){ topk(n,M,k,1); continue; }
    int viol=0;
    for(int i=0;i<n;i++){const double*Mi=M+(size_t)i*n; double ui=u[i]; char*hi=has+(size_t)i*n;
      for(int j=0;j<n;j++){ if(Mi[j]-ui-v[j]< -1e-12 && !hi[j]){adj[(size_t)i*n+cnt[i]++]=j;hi[j]=1;viol++;}}}
    TT[4]+=now()-a1;
    if(!viol){ret=it;break;}
  }
