static void* th_check(void*p){TA*a=p;int n=a->n;int r0=(long)a->id*n/NTH,r1=(long)(a->id+1)*n/NTH; int added=0;
  for(int i=r0;i<r1;i++){const double*Mi=a->M+(size_t)i*n; double th=u[i]-1e-12; g_flag[i]=0;
      for(int j=0;j<n;j++){ if(Mi[j]-v[j]<th && !hasedge(i,j)){addedge(i,j,Mi[j]);added++;g_flag[i]=1;} } }
  a->added=added; return 0;}
static int runpar(void*(*f)(void*),int n,int k,const double*M){
  pthread_t th[NTH]; TA ta[NTH];
  for(int t=0;t<NTH;t++){ta[t].id=t;ta[t].n=n;ta[t].k=k;ta[t].M=M;ta[t].added=0; if(t>0)pthread_create(&th[t],0,f,&ta[t]);}
  f(&ta[0]); int s=ta[0].added;
  for(int t=1;t<NTH;t++){pthread_join(th[t],0); s+=ta[t].added;}
  return s;
}

int solve(int n,const double*M,int k,double eps0,double epsf,double epsmin,int*c4r){
  double T0=now(); memset(ST,0,sizeof ST);
  if(k>n)k=n;
  ensure(n,(k*3+64<n+1)?k*3+64:n+1);
  char flag[n]; g_flag=flag;
  { double est[9]; double*buf=sh; int ns=9;
    for(int s_=0;s_<ns;s_++){ int i=(int)((long)(2*s_+1)*n/(2*ns)); const double*Mi=M+(size_t)i*n; memcpy(buf,Mi,n*8); qsort(buf,n,8,cmpd); est[s_]=buf[k-1]-buf[0]; }
    qsort(est,ns,8,cmpd); g_c=est[ns/2]*GCF; for(int j=0;j<n;j++)sh[j]=INFINITY; }
  runpar(th_filter,n,k,M);
  if(overflow) return -3;
  for(int j=0;j<n;j++){v[j]=INFINITY;r4c[j]=-1;}
  for(int i=0;i<n;i++){const int*a=ej+(size_t)i*S;const double*cc=ec+(size_t)i*S;for(int t=0;t<cnt[i];t++){int j=a[t]; if(cc[t]<v[j])v[j]=cc[t];}}
  for(int i=0;i<n;i++)c4r[i]=-1;
  double T1=now();
  int nf=0; for(int i=0;i<n;i++)stk[nf++]=i;
  for(double eps=eps0;;){
    if(auction(n,c4r,eps,CAPF*(long)n+10000,nf)) return -4;
    if(eps<=epsmin)break;
    eps*=epsf; if(eps<epsmin)eps=epsmin;
    nf=unassign_viol(n,c4r,eps);
  }
  double T2=now();
  if(spfa(n,c4r)) return -5;
  int ret=-1;
  for(int outer=0;outer<100;outer++){
    int added=runpar(th_check,n,k,M);
    if(overflow) return -3;
    ST[1]+=added;
    if(!added){ret=outer;break;}
    /* rows with new edges: lower u to restore feasibility, unassign */
    for(int i=0;i<n;i++) if(flag[i]){ const int*a=ej+(size_t)i*S;const double*cc=ec+(size_t)i*S; double mn=INFINITY;
      for(int t=0;t<cnt[i];t++){double r=cc[t]-v[a[t]]; mn=r<mn?r:mn;} u[i]=mn; int c=c4r[i]; c4r[i]=-1; r4c[c]=-1; }
    if(sap(n,c4r)) return -2;
  }
  TT[0]=T1-T0; TT[1]=T2-T1; TT[2]=now()-T2;
  return ret;
}
